1	"use client";
2	
3	import { useEffect, useState } from "react";
4	import Link from "next/link";
5	import { useRouter } from "next/navigation";
6	import {
7	  getExportUrl,
8	  getRequirements,
9	  getScenarios,
10	  putWeights,
11	  type Requirement,
12	  type Scenario,
13	  type WeightKey,
14	  type Weights,
15	} from "@/src/lib/api";
16	import { categoryLabel } from "@/src/components/badges";
17	import { ScoreBar } from "@/src/components/ScoreBar";
18	import { ThemeToggle } from "@/src/components/ThemeToggle";
19	
20	const DEFAULT_SCENARIO_ID = "G60-US";
21	const PM_ACTOR = "pm.demo";
22	const DEFAULT_WEIGHTS: Record<WeightKey, number> = {
23	  customer_pain: 0.25,
24	  reach: 0.2,
25	  satisfaction_gap: 0.2,
26	  competitive_pressure: 0.15,
27	  future_relevance: 0.1,
28	  effort_inverse: 0.1,
29	};
30	
31	const WEIGHT_LABELS: Record<WeightKey, string> = {
32	  customer_pain: "Customer pain",
33	  reach: "Reach",
34	  satisfaction_gap: "Satisfaction gap",
35	  competitive_pressure: "Competitive pressure",
36	  future_relevance: "Future relevance",
37	  effort_inverse: "Low effort",
38	};
39	
40	const DEMO_RATIONALE = "Demo adjustment: product management is testing a different prioritization focus.";
41	
42	function scenarioLabel(scenario: Scenario) {
43	  return `${scenario.model_name} ${scenario.market}`;
44	}
45	
46	function weightsFromRequirements(requirements: Requirement[]): Record<WeightKey, number> {
47	  const first = requirements[0]?.score_breakdown;
48	  return {
49	    customer_pain: first?.customer_pain?.weight ?? DEFAULT_WEIGHTS.customer_pain,
50	    reach: first?.reach?.weight ?? DEFAULT_WEIGHTS.reach,
51	    satisfaction_gap: first?.satisfaction_gap?.weight ?? DEFAULT_WEIGHTS.satisfaction_gap,
52	    competitive_pressure: first?.competitive_pressure?.weight ?? DEFAULT_WEIGHTS.competitive_pressure,
53	    future_relevance: first?.future_relevance?.weight ?? DEFAULT_WEIGHTS.future_relevance,
54	    effort_inverse: first?.effort_inverse?.weight ?? DEFAULT_WEIGHTS.effort_inverse,
55	  };
56	}
57	
58	export default function RequirementsPage() {
59	  const router = useRouter();
60	  const [scenarios, setScenarios] = useState<Scenario[]>([]);
61	  const [scenarioId, setScenarioId] = useState(DEFAULT_SCENARIO_ID);
62	  const [requirements, setRequirements] = useState<Requirement[]>([]);
63	  const [weights, setWeights] = useState<Record<WeightKey, number>>(DEFAULT_WEIGHTS);
64	  const [rationale, setRationale] = useState("");
65	  const [previousRanks, setPreviousRanks] = useState<Record<string, number>>({});
66	  const [highlightRanks, setHighlightRanks] = useState(false);
67	  const [loading, setLoading] = useState(true);
68	  const [applying, setApplying] = useState(false);
69	  const [error, setError] = useState<string | null>(null);
70	
71	  useEffect(() => {
72	    getScenarios()
73	      .then((loaded) => {
74	        setScenarios(loaded);
75	        if (!loaded.some((scenario) => scenario.id === DEFAULT_SCENARIO_ID) && loaded[0]) {
76	          setScenarioId(loaded[0].id);
77	        }
78	      })
79	      .catch((err: Error) => setError(err.message));
80	  }, []);
81	
82	  useEffect(() => {
83	    let cancelled = false;
84	    getRequirements(scenarioId)
85	      .then((nextRequirements) => {
86	        if (cancelled) return;
87	        setRequirements(nextRequirements);
88	        setWeights(weightsFromRequirements(nextRequirements));
89	        setError(null);
90	      })
91	      .catch((err: Error) => {
92	        if (!cancelled) setError(err.message);
93	      })
94	      .finally(() => {
95	        if (!cancelled) setLoading(false);
96	      });
97	    return () => {
98	      cancelled = true;
99	    };
100	  }, [scenarioId]);
101	
102	  const selectedScenario = scenarios.find((scenario) => scenario.id === scenarioId);
103	
104	  async function applyWeights(nextWeights: Weights = weights) {
105	    if (applying) return;
106	    const appliedRationale = rationale.trim() || DEMO_RATIONALE;
107	    setApplying(true);
108	    setError(null);
109	    const before = Object.fromEntries(requirements.map((req) => [req.id, req.rank]));
110	    try {
111	      const reranked = await putWeights(scenarioId, {
112	        weights: nextWeights,
113	        actor: PM_ACTOR,
114	        rationale: appliedRationale,
115	      });
116	      setPreviousRanks(before);
117	      setRequirements(reranked);
118	      setWeights(weightsFromRequirements(reranked));
119	      setRationale("");
120	      setHighlightRanks(true);
121	      window.setTimeout(() => setHighlightRanks(false), 2000);
122	    } catch (err) {
123	      setError((err as Error).message);
124	    } finally {
125	      setApplying(false);
126	    }
127	  }
128	
129	  function resetWeights() {
130	    setWeights(DEFAULT_WEIGHTS);
131	  }
132	
133	  return (
134	    <main className="min-h-screen px-4 py-6 sm:px-6 lg:px-8">
135	      <div className="mx-auto grid max-w-7xl gap-6 xl:grid-cols-[1fr_360px]">
136	        <section className="min-w-0">
137	          <header className="mb-5 rounded-lg border border-zinc-200 dark:border-zinc-800 bg-surface p-5">
138	            <div className="flex flex-wrap items-start justify-between gap-4">
139	              <div>
140	                <p className="text-xs font-semibold uppercase tracking-wide text-zinc-500 dark:text-zinc-400">Signal2Spec</p>
141	                <h1 className="mt-1 text-2xl font-semibold text-foreground">PM Cockpit</h1>
142	                <p className="mt-1 max-w-2xl text-sm text-zinc-600 dark:text-zinc-400">
143	                  Decide what the AI proposes, why it proposes it, and how reliable the evidence is.
144	                </p>
145	              </div>
146	              <nav className="flex flex-wrap gap-2">
147	                <Link className="inline-flex min-h-11 items-center rounded-sm border border-zinc-300 dark:border-zinc-700 bg-surface px-4 text-sm font-semibold text-foreground hover:bg-zinc-50 dark:hover:bg-zinc-900 focus:outline-none focus-visible:ring-2 focus-visible:ring-accent/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background" href="/audit">
148	                  Audit trail
149	                </Link>
150	                <a className="inline-flex min-h-11 items-center rounded-sm bg-accent px-4 text-sm font-semibold text-white hover:bg-accent-hover focus:outline-none focus-visible:ring-2 focus-visible:ring-accent/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background" href={getExportUrl(scenarioId)} target="_blank" rel="noopener noreferrer">
151	                  Export CSV
152	                </a>
153	                <ThemeToggle />
154	              </nav>
155	            </div>
156	
157	            <div className="mt-5 flex flex-wrap items-center gap-3">
158	              <label className="grid gap-1 text-sm font-semibold text-zinc-700 dark:text-zinc-300">
159	                Scenario
160	                <select
161	                  value={scenarioId}
162	                  onChange={(event) => {
163	                    setLoading(true);
164	                    setError(null);
165	                    setScenarioId(event.target.value);
166	                  }}
167	                  className="min-h-11 rounded-sm border border-zinc-300 dark:border-zinc-700 bg-surface px-3 font-normal text-foreground focus:border-accent focus:outline-none"
168	                >
169	                  {scenarios.map((scenario) => (
170	                    <option key={scenario.id} value={scenario.id}>
171	                      {scenarioLabel(scenario)}
172	                    </option>
173	                  ))}
174	                </select>
175	              </label>
176	              {selectedScenario?.headline_numbers && (
177	                <div className="grid grid-cols-3 gap-2 text-xs text-zinc-600 dark:text-zinc-400">
178	                  <span className="rounded-sm border border-zinc-200 dark:border-zinc-800 bg-zinc-50 dark:bg-zinc-900 px-3 py-2">
179	                    {selectedScenario.headline_numbers.evidence.toLocaleString("en-US")} customer voices
180	                  </span>
181	                  <span className="rounded-sm border border-zinc-200 dark:border-zinc-800 bg-zinc-50 dark:bg-zinc-900 px-3 py-2">
182	                    {selectedScenario.headline_numbers.signals} findings
183	                  </span>
184	                  <span className="rounded-sm border border-zinc-200 dark:border-zinc-800 bg-zinc-50 dark:bg-zinc-900 px-3 py-2">
185	                    {selectedScenario.headline_numbers.requirements} requirements
186	                  </span>
187	                </div>
188	              )}
189	            </div>
190	          </header>
191	
192	          {error && (
193	            <div className="mb-4 rounded-sm border border-rose-300 bg-rose-50 px-4 py-3 text-sm text-rose-800 dark:border-rose-800 dark:bg-rose-950 dark:text-rose-300">
194	              {error}
195	            </div>
196	          )}
197	
198	          <div className="overflow-hidden rounded-lg border border-zinc-200 dark:border-zinc-800 bg-surface">
199	            {loading && <p className="p-5 text-sm text-zinc-500 dark:text-zinc-400">Loading requirements...</p>}
200	            {!loading && requirements.length === 0 && (
201	              <p className="p-5 text-sm text-zinc-500 dark:text-zinc-400">No requirements for this scenario yet.</p>
202	            )}
203	            {!loading && requirements.length > 0 && (
204	              <div className="overflow-x-auto">
205	                <table className="w-full min-w-[900px] text-left text-sm">
206	                  <thead className="border-b border-zinc-200 dark:border-zinc-800 bg-zinc-50 dark:bg-zinc-900 text-xs uppercase tracking-wide text-zinc-500 dark:text-zinc-400">
207	                    <tr>
208	                      <th className="px-4 py-3">Score</th>
209	                      <th className="px-4 py-3">Title</th>
210	                      <th className="px-4 py-3">Category</th>
211	                    </tr>
212	                  </thead>
213	                  <tbody>
214	                    {requirements.map((req) => (
215	                      <tr
216	                        key={req.id}
217	                        role="link"
218	                        tabIndex={0}
219	                        onClick={() => router.push(`/requirements/${req.id}`)}
220	                        onKeyDown={(event) => {
221	                          if (event.key === "Enter" || event.key === " ") {
222	                            event.preventDefault();
223	                            router.push(`/requirements/${req.id}`);
224	                          }
225	                        }}
226	                        className={`cursor-pointer border-b border-zinc-100 dark:border-zinc-800 transition last:border-0 hover:bg-accent/5 dark:hover:bg-accent/10 focus:bg-accent/5 dark:focus:bg-accent/10 focus:outline-none ${
227	                          highlightRanks && previousRanks[req.id] !== req.rank ? "bg-accent/5 dark:bg-accent/10" : ""
228	                        }`}
229	                      >
230	                        <td className="px-4 py-4">
231	                          <ScoreBar score={req.score} source={`${req.signal_ids.length} linked findings`} />
232	                        </td>
233	                        <td className="max-w-sm px-4 py-4">
234	                          <p className="font-semibold text-foreground">{req.title}</p>
235	                          <p className="mt-1 line-clamp-2 text-xs text-zinc-500 dark:text-zinc-400">{req.description}</p>
236	                        </td>
237	                        <td className="px-4 py-4 text-zinc-700 dark:text-zinc-300">{categoryLabel(req.category)}</td>
238	                      </tr>
239	                    ))}
240	                  </tbody>
241	                </table>
242	              </div>
243	            )}
244	          </div>
245	        </section>
246	
247	        <aside className="grid h-fit gap-4 xl:sticky xl:top-6">
248	          <section className="theme-dark-fixed rounded-lg border border-accent/30 bg-accent/5 p-5">
249	            <h2 className="text-sm font-semibold uppercase tracking-wide text-foreground">Demo navigation</h2>
250	            <ol className="mt-3 grid gap-2 text-sm text-foreground">
251	              <li><span className="font-semibold">1.</span> Pick a scenario and scan the ranked list.</li>
252	              <li><span className="font-semibold">2.</span> Open a row to inspect evidence, assumptions, and score logic.</li>
253	              <li><span className="font-semibold">3.</span> Approve, reject, edit, or challenge with a rationale.</li>
254	              <li><span className="font-semibold">4.</span> Open Audit trail to show the decision record.</li>
255	            </ol>
256	          </section>
257	
258	          <section className="rounded-lg border border-zinc-200 dark:border-zinc-800 bg-surface p-5">
259	          <h2 className="text-sm font-semibold uppercase tracking-wide text-zinc-500 dark:text-zinc-400">Weight controls</h2>
260	          <p className="mt-2 text-sm text-zinc-600 dark:text-zinc-400">
261	            Move sliders and press Apply weights. Empty rationale uses a demo rationale and still records changed weights.
262	          </p>
263	          <div className="mt-4 grid gap-4">
264	            {(Object.keys(WEIGHT_LABELS) as WeightKey[]).map((key) => (
265	              <label key={key} className="grid gap-2 text-sm font-semibold text-zinc-700 dark:text-zinc-300">
266	                <span className="flex items-center justify-between gap-3">
267	                  {WEIGHT_LABELS[key]}
268	                  <span className="text-xs font-semibold text-zinc-500 dark:text-zinc-400">{weights[key].toFixed(2)}</span>
269	                </span>
270	                <input
271	                  type="range"
272	                  min="0"
273	                  max="0.6"
274	                  step="0.01"
275	                  value={weights[key]}
276	                  onChange={(event) =>
277	                    setWeights((value) => ({ ...value, [key]: Number(event.target.value) }))
278	                  }
279	                  className="h-2 accent-[var(--accent)]"
280	                />
281	              </label>
282	            ))}
283	          </div>
284	          <div className="mt-4 flex flex-wrap gap-2">
285	            <button
286	              type="button"
287	              disabled={applying}
288	              onClick={() => applyWeights()}
289	              className="min-h-11 rounded-sm bg-accent px-4 text-sm font-semibold text-white hover:bg-accent-hover focus:outline-none focus-visible:ring-2 focus-visible:ring-accent/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:cursor-not-allowed disabled:bg-zinc-300 dark:disabled:bg-zinc-700"
290	            >
291	              {applying ? "Applying..." : "Apply weights"}
292	            </button>
293	            <button
294	              type="button"
295	              onClick={resetWeights}
296	              className="min-h-11 rounded-sm border border-zinc-300 dark:border-zinc-700 bg-surface px-4 text-sm font-semibold text-foreground hover:bg-zinc-50 dark:hover:bg-zinc-900 focus:outline-none focus-visible:ring-2 focus-visible:ring-accent/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background"
297	            >
298	              Reset to default
299	            </button>
300	          </div>
301	          </section>
302	        </aside>
303	      </div>
304	    </main>
305	  );
306	}
