317	async function request<T>(path: string, init?: RequestInit): Promise<T> {
318	  let response: Response;
319	  try {
320	    response = await fetch(`${BASE_URL}${path}`, {
321	      headers: { "Content-Type": "application/json", ...(init?.headers ?? {}) },
322	      ...init,
323	    });
324	  } catch {
325	    throw new Error("Backend not reachable – start uvicorn");
326	  }
327	
328	  if (!response.ok) {
329	    const detail = await response
330	      .json()
331	      .then((body: { detail?: string }) => body.detail)
332	      .catch(() => undefined);
333	    throw new Error(detail ?? `Request failed: ${response.status} ${response.statusText}`);
334	  }
335	
336	  return response.json() as Promise<T>;
337	}
