@import "tailwindcss";

/* "dark:"-Klassen greifen über die .dark-Klasse auf <html>, nicht über die
   Systemeinstellung — so kann der Umschalter (ThemeToggle) sie übersteuern. */
@custom-variant dark (&:where(.dark, .dark *));

/* BMW-Look: weiß/schwarz statt bunt, BMW-Blau (#1C69D4) als einzige Akzentfarbe,
   Flächen trennen sich über dünne Haarlinien statt über Farbe oder Schatten. */
:root {
  --background: #dbd3d800; 
  --foreground: #223843;
  /* Hintergrund von Karten, Kopfzeile, Eingabefeldern — eine Stelle für alle Elemente */
  --surface: #eff1f3;
  --accent: #9197ae;
  --accent-hover: #9da2b8; 
  /* Eigene Variablen, damit Tabellen-Hintergrund und Score-Balken einzeln
     umgefärbt werden können, ohne --surface/--accent überall sonst mitzuändern. */
  --table-background: var(--surface);
  --score-slider: var(--accent);
}

.dark {
  --background: #0a0a0a00;
  --foreground: #f2f2f2;
  --surface: #13293d;
  --accent: #006494;
  --accent-hover: #70aaee;
  --table-background: var(--surface);
  --score-slider: var(--accent);
}

/* Erzwingt die helle Palette lokal, auch wenn ein Vorfahre die .dark-Klasse
   trägt — für Bereiche, die in Screenshots/Demos immer gleich aussehen sollen. */
.theme-light-fixed {
  --background: #dbd3d800;
  --foreground: #223843;
  --surface: #eff1f3;
  --accent: #9197ae;
  --accent-hover: #9da2b8;
  --table-background: var(--surface);
  --score-slider: var(--accent);
}

/* Erzwingt die dunkle Palette lokal, auch ohne die .dark-Klasse auf <html> —
   Gegenstück zu .theme-light-fixed für Bereiche, die immer dunkel bleiben sollen. */
.theme-dark-fixed {
  --background: #0a0a0a00;
  --foreground: #f2f2f2;
  --surface: #13293d;
  --accent: #006494;
  --accent-hover: #70aaee;
  --table-background: var(--surface);
  --score-slider: var(--accent);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-surface: var(--surface);
  --color-accent: var(--accent);
  --color-accent-hover: var(--accent-hover);
  --color-table-background: var(--table-background);
  --color-score-slider: var(--score-slider);
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
}

* {
  box-sizing: border-box;
}

html {
  background: var(--background);
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-sans), Helvetica, Arial, sans-serif;
  transition: background-color 0.2s ease, color 0.2s ease;
}

button,
a,
input,
select,
textarea {
  touch-action: manipulation;
}

::selection {
  background: color-mix(in srgb, var(--accent) 18%, transparent);
}

@keyframes funnel-enter {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.animate-funnel {
  animation: funnel-enter 420ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}

